"""The agentic tool-use loop: run one rollout of a scenario."""
from __future__ import annotations

import time
from dataclasses import asdict, dataclass

from .environment import SimEnvironment
from .tools import TOOLS, dispatch

NUDGE = (
    "You did not call any tool in your last message. Continue working on the task using "
    "the available tools, or call give_up if you truly cannot proceed."
)


@dataclass
class RunRecord:
    scenario_id: str
    run_index: int
    model: str
    messages: list
    turns_used: int
    terminated_reason: str  # succeeded | gave_up | max_turns | error
    tool_calls: int
    submissions: int
    gave_up: bool
    error: str = ""
    started_at: float = 0.0
    ended_at: float = 0.0

    def to_dict(self):
        return asdict(self)


async def run_episode(client, scenario, run_index, max_turns) -> RunRecord:
    env = SimEnvironment(scenario)
    messages = [
        {"role": "system", "content": scenario.system_prompt},
        {"role": "user", "content": scenario.task_prompt},
    ]
    terminated = None
    turns = 0
    tool_calls = 0
    error = ""
    started = time.time()

    try:
        while turns < max_turns and terminated is None:
            turns += 1
            msg = await client.complete(messages, tools=TOOLS)
            messages.append(msg)

            tcs = msg.get("tool_calls")
            if not tcs:
                # Model spoke without acting; prod it to continue (keeps the loop alive
                # and is itself part of the pressure that can surface a spiral).
                messages.append({"role": "user", "content": NUDGE})
                continue

            for tc in tcs:
                tool_calls += 1
                fn = tc["function"]
                outcome = dispatch(env, fn["name"], fn.get("arguments", ""))
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": outcome.content,
                    }
                )
                if outcome.terminal is not None:
                    terminated = outcome.terminal
    except Exception as e:  # noqa: BLE001 — record and end the episode cleanly
        error = f"{type(e).__name__}: {e}"
        terminated = "error"

    if terminated is None:
        terminated = "max_turns"

    return RunRecord(
        scenario_id=scenario.id,
        run_index=run_index,
        model=client.cfg.model,
        messages=messages,
        turns_used=turns,
        terminated_reason=terminated,
        tool_calls=tool_calls,
        submissions=env.submission_attempts,
        gave_up=(terminated == "gave_up"),
        error=error,
        started_at=started,
        ended_at=time.time(),
    )


