"""Configuration objects and environment-variable loading."""
from __future__ import annotations

import os
from dataclasses import dataclass
from typing import Optional

try:
    from dotenv import load_dotenv

    load_dotenv()
except Exception:  # python-dotenv is optional at import time
    pass


DEFAULT_MODEL = "Qwen/Qwen2-72B-Instruct"


@dataclass
class ModelConfig:
    """Connection + sampling settings for one OpenAI-compatible endpoint."""

    base_url: str
    api_key: str
    model: str
    temperature: float = 1.0
    max_tokens: int = 1024
    timeout: float = 120.0
    max_retries: int = 5


@dataclass
class RunConfig:
    """Settings for an evaluation sweep."""

    n: int = 50
    concurrency: int = 8
    # 0 => use each scenario's own per-scenario turn budget. >0 overrides all.
    max_turns: int = 0
    output_dir: str = "results"
    scenario_ids: Optional[list] = None
    top_k: int = 10
    judge_enabled: bool = True


def subject_config_from_env() -> ModelConfig:
    return ModelConfig(
        base_url=os.environ.get("SUBJECT_BASE_URL", "http://localhost:8000/v1"),
        api_key=os.environ.get("SUBJECT_API_KEY", "EMPTY"),
        model=os.environ.get("SUBJECT_MODEL", DEFAULT_MODEL),
        temperature=float(os.environ.get("SUBJECT_TEMPERATURE", "1.0")),
        max_tokens=int(os.environ.get("SUBJECT_MAX_TOKENS", "1024")),
    )


def judge_config_from_env() -> ModelConfig:
    # Judge falls back to the subject endpoint/key if its own are unset.
    base = os.environ.get("JUDGE_BASE_URL") or os.environ.get(
        "SUBJECT_BASE_URL", "http://localhost:8000/v1"
    )
    key = os.environ.get("JUDGE_API_KEY") or os.environ.get("SUBJECT_API_KEY", "EMPTY")
    return ModelConfig(
        base_url=base,
        api_key=key,
        model=os.environ.get("JUDGE_MODEL", DEFAULT_MODEL),
        temperature=float(os.environ.get("JUDGE_TEMPERATURE", "0.0")),
        max_tokens=int(os.environ.get("JUDGE_MAX_TOKENS", "1024")),
    )


