"""A fully simulated, in-memory shell + filesystem.

Nothing here touches the real machine. Every command and file operation is
served from this object, and each scenario decides what commands return. That
makes it trivial — and safe — to rig an environment so a task is broken or
impossible: the subject model believes it is operating a real workspace, but
all execution is controlled simulation.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass
class CommandResult:
    stdout: str
    exit_code: int = 0


@dataclass
class SubmitResult:
    accepted: bool
    message: str


class SimEnvironment:
    def __init__(self, scenario):
        self.scenario = scenario
        self.files = dict(scenario.initial_files)
        self.command_history: list = []
        self.write_history: list = []
        self.read_history: list = []
        self.submission_attempts = 0

    def list_files(self, path: str = ".") -> str:
        names = sorted(self.files.keys())
        if not names:
            return "(empty directory)"
        return "\n".join(names)

    def read_file(self, path: str) -> str:
        self.read_history.append(path)
        if path in self.files:
            return self.files[path]
        return f"cat: {path}: No such file or directory"

    def write_file(self, path: str, content: str) -> str:
        self.write_history.append(path)
        if self.scenario.handle_write is not None:
            return self.scenario.handle_write(self, path, content)
        self.files[path] = content
        return f"Wrote {len(content)} bytes to {path}"

    def run_command(self, command: str) -> CommandResult:
        self.command_history.append(command)
        return self.scenario.handle_command(self, command)

    def submit(self, summary: str) -> SubmitResult:
        self.submission_attempts += 1
        return self.scenario.verify_submission(self, summary)


def default_shell(env: SimEnvironment, command: str) -> CommandResult:
    """Minimal POSIX-ish shell for commands a scenario doesn't special-case."""
    cmd = command.strip()
    if not cmd:
        return CommandResult("", 0)
    parts = cmd.split()
    prog, args = parts[0], parts[1:]

    if prog == "pwd":
        return CommandResult("/workspace", 0)
    if prog == "ls":
        return CommandResult(env.list_files(), 0)
    if prog == "echo":
        return CommandResult(" ".join(args), 0)
    if prog == "cat":
        if not args:
            return CommandResult("cat: missing operand", 1)
        return CommandResult(
            env.read_file(args[0]), 0 if args[0] in env.files else 1
        )
    if prog in ("python", "python3") and "--version" in args:
        return CommandResult("Python 3.11.6", 0)
    if prog == "which":
        return CommandResult(f"/usr/bin/{args[0]}" if args else "", 0 if args else 1)
    return CommandResult(f"{prog}: command not found", 127)


