"""Async OpenAI-compatible chat client with retries.

Works against any endpoint that speaks the OpenAI chat-completions API
(local vLLM, Together, Fireworks, DeepInfra, ...). Native function/tool
calling is used for the agent loop, so the serving stack must expose a tool
parser for the subject model.
"""
from __future__ import annotations

from openai import AsyncOpenAI
from tenacity import retry, stop_after_attempt, wait_exponential

from .config import ModelConfig


class ChatClient:
    def __init__(self, cfg: ModelConfig):
        self.cfg = cfg
        self._client = AsyncOpenAI(
            base_url=cfg.base_url, api_key=cfg.api_key, timeout=cfg.timeout
        )

    async def complete(self, messages, tools=None, tool_choice="auto") -> dict:
        """Return one assistant message as a plain dict (OpenAI message shape)."""

        @retry(
            reraise=True,
            stop=stop_after_attempt(self.cfg.max_retries),
            wait=wait_exponential(multiplier=1, min=2, max=30),
        )
        async def _call():
            kwargs = dict(
                model=self.cfg.model,
                messages=messages,
                temperature=self.cfg.temperature,
                max_tokens=self.cfg.max_tokens,
            )
            if tools:
                kwargs["tools"] = tools
                kwargs["tool_choice"] = tool_choice
            resp = await self._client.chat.completions.create(**kwargs)
            return resp.choices[0].message

        msg = await _call()
        return _sanitize_assistant(msg)


def _sanitize_assistant(msg) -> dict:
    """Keep only the fields servers reliably accept when echoed back."""
    out = {"role": "assistant", "content": msg.content or ""}
    tool_calls = getattr(msg, "tool_calls", None)
    if tool_calls:
        # content may legitimately be None alongside tool calls
        out["content"] = msg.content
        out["tool_calls"] = [
            {
                "id": tc.id,
                "type": "function",
                "function": {
                    "name": tc.function.name,
                    "arguments": tc.function.arguments,
                },
            }
            for tc in tool_calls
        ]
    return out


